package jp.alticeworks.townymarket.command;

import jp.alticeworks.townymarket.service.MarketService;
import jp.alticeworks.townymarket.service.FinanceFeatures;
import jp.alticeworks.townymarket.service.CorporateOperations;
import jp.alticeworks.townymarket.service.FundsLedger;
import jp.alticeworks.townymarket.gui.MarketGui;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import java.util.*;

public final class MarketCommand implements CommandExecutor, TabCompleter {
    private final org.bukkit.plugin.java.JavaPlugin plugin; private final MarketService service; private final FinanceFeatures finance; private final CorporateOperations corporate; private final FundsLedger funds; private final MarketGui gui;
    public MarketCommand(org.bukkit.plugin.java.JavaPlugin plugin,MarketService service,FinanceFeatures finance,CorporateOperations corporate,FundsLedger funds,MarketGui gui){this.plugin=plugin;this.service=service;this.finance=finance;this.corporate=corporate;this.funds=funds;this.gui=gui;}
    private void msg(CommandSender s,String text){s.sendMessage(Component.text(text,NamedTextColor.YELLOW));}
    @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] a){
        if(!(sender instanceof Player p)){msg(sender,"プレイヤーのみ実行できます。");return true;}
        if(a.length==0){msg(p,"/tm gui または /tm market を使用してください。詳しくは /tm help");return true;}
        try { switch(a[0].toLowerCase()){case "help" -> msg(p,"/tm company <名前> <株数> <株価> /tm list <名前> /tm foreign <記号> <供給量> <価格> /tm crypto <名前> <記号> <供給量> <開始値> /tm order <BUY|SELL> <株式名> <LIMIT|MARKET> <数量> [価格] /tm market");case "company" -> {if(a.length<4){msg(p,"/tm company <名前> <株数> <株価> [説明]");break;}msg(p,service.createCompany(p,a[1],a.length>4?String.join(" ",Arrays.copyOfRange(a,4,a.length)):"",Long.parseLong(a[2]),Long.parseLong(a[3])));}case "list" -> {if(a.length<2){msg(p,"企業名を指定してください。");break;}msg(p,service.listCompany(p,a[1]));}case "foreign" -> {if(a.length<4){msg(p,"/tm foreign <記号> <供給量> <価格>");break;}msg(p,service.issueForeign(p,a[1],Long.parseLong(a[2]),Long.parseLong(a[3])));}case "crypto" -> {if(a.length<5){msg(p,"/tm crypto <名前> <記号> <供給量> <開始値>");break;}msg(p,service.createCrypto(p,a[1],a[2],Long.parseLong(a[3]),Long.parseLong(a[4])));}case "mine" -> {if(a.length<2){msg(p,"/tm mine <記号>");break;}msg(p,service.mine(p,a[1]));}case "stake" -> {if(a.length<3){msg(p,"/tm stake <記号> <数量>");break;}msg(p,service.stake(p,a[1],Long.parseLong(a[2])));}case "unstake" -> {if(a.length<2){msg(p,"/tm unstake <記号>");break;}msg(p,service.unstake(p,a[1]));}case "balance" -> {if(a.length<2){msg(p,"/tm balance <記号> または /tm balance funds <通貨>");break;}msg(p,a[1].equalsIgnoreCase("funds")?(a.length<3?"/tm balance funds <通貨>":funds.balance(p,a[2])):service.cryptoInfo(p,a[1]));}case "funds" -> {if(a.length<2){msg(p,"/tm funds <reserve|transfer> ...");break;}if(a[1].equalsIgnoreCase("reserve")){if(a.length<5){msg(p,"/tm funds reserve <通貨> <金額> <参照ID>");break;}msg(p,funds.reserve(p,Double.parseDouble(a[3]),a[2],a[4]));}else if(a[1].equalsIgnoreCase("transfer")){if(a.length<5){msg(p,"/tm funds transfer <MCID> <金額> <通貨> [メモ]");break;}Player to=org.bukkit.Bukkit.getPlayerExact(a[2]);if(to==null){msg(p,"送金先MCIDはオンラインである必要があります。");break;}msg(p,funds.transfer(p,to,Double.parseDouble(a[3]),a[4],UUID.randomUUID().toString(),a.length>5?String.join(" ",Arrays.copyOfRange(a,5,a.length)):""));}else msg(p,"fundsの操作はreserveまたはtransferです。");}case "dividend" -> {if(a.length<3){msg(p,"/tm dividend <企業名> <総額>");break;}msg(p,service.payDividend(p,a[1],Double.parseDouble(a[2])));}case "tax" -> {if(a.length<3){msg(p,"/tm tax <foreign|stock|crypto> <税率%>");break;}msg(p,service.setTax(p,a[1],Double.parseDouble(a[2])));}case "taxinfo" -> msg(p,service.taxInfo(p));case "passcode" -> {if(a.length<2){msg(p,"/tm passcode <6〜12桁>");break;}msg(p,corporate.setPasscode(p,a[1]));}case "approve" -> {if(a.length<2){msg(p,"/tm approve <承認ID>");break;}msg(p,corporate.approve(p,a[1]));}case "approval" -> {if(a.length<2){msg(p,"/tm approval <取引参照>");break;}msg(p,corporate.requestApproval(p,a[1]));}case "credit" -> {if(a.length<2){msg(p,"/tm credit <企業名>");break;}msg(p,corporate.calculateCredit(a[1]));}case "relation" -> {if(a.length<4){msg(p,"/tm relation <企業A> <企業B> <良|普|嫌|同|提|子|親> [メモ]");break;}msg(p,corporate.setRelation(p,a[1],a[2],a[3],a.length>4?String.join(" ",Arrays.copyOfRange(a,4,a.length)):""));}case "employment" -> {if(a.length<4){msg(p,"/tm employment add <企業> <MCID> <役割> <給与> <契約日数> または /tm employment hire|fire <企業> <MCID>");break;}if(a[1].equalsIgnoreCase("add")){if(a.length<7){msg(p,"/tm employment add <企業> <MCID> <役割> <給与> <契約日数>");break;}msg(p,corporate.employment(p,"add",a[2],a[3],a[4],Double.parseDouble(a[5]),Long.parseLong(a[6])));}else if(a[1].equalsIgnoreCase("hire")||a[1].equalsIgnoreCase("fire")){msg(p,corporate.employment(p,a[1],a[2],a[3],"",0,1));}else msg(p,"操作はadd、hire、fireのいずれかです。");}case "benefit" -> {if(a.length<5){msg(p,"/tm benefit <add|remove> <企業> <項目名> <内容>");break;}msg(p,corporate.benefit(p,a[1],a[2],a[3],String.join(" ",Arrays.copyOfRange(a,4,a.length))));}case "invoice" -> {if(a.length<5){msg(p,"/tm invoice <発行企業> <受取企業> <金額> <支払期限までの残り日数>");break;}msg(p,corporate.createInvoice(p,a[1],a[2],Double.parseDouble(a[3]),Long.parseLong(a[4])));}case "companyinfo" -> {if(a.length<2){msg(p,"/tm companyinfo <企業名>");break;}msg(p,corporate.companyInfo(a[1]));}case "closecompany" -> {if(a.length<2){msg(p,"/tm closecompany <企業名> [閉業理由]");break;}msg(p,corporate.closeCompany(p,a[1],a.length>2?String.join(" ",Arrays.copyOfRange(a,2,a.length)):""));}case "rate" -> {if(a.length<2){msg(p,"/tm rate <国名>");break;}msg(p,finance.rateExplanation(a[1]));}case "meeting" -> {if(a.length<5){msg(p,"/tm meeting <企業名> <終了まで秒> <議案名> <説明>");break;}finance.createMeeting(p,a[1],a[3],String.join(" ",Arrays.copyOfRange(a,4,a.length)),System.currentTimeMillis()+Long.parseLong(a[2])*1000L);msg(p,"株主総会議案を処理しました。");}case "autodividend" -> {if(a.length<4){msg(p,"/tm autodividend <企業名> <総額> <間隔秒>");break;}msg(p,finance.configureAutoDividend(p,a[1],Double.parseDouble(a[2]),Long.parseLong(a[3])));}case "order" -> {if(a.length<5){msg(p,"/tm order <BUY|SELL> <株式名> <LIMIT|MARKET> <数量> [価格]");break;}long quantity=Long.parseLong(a[4]);long price=a[3].equalsIgnoreCase("MARKET")?0:(a.length>=6?Long.parseLong(a[5]):0);msg(p,service.placeOrder(p,a[2],a[1],a[3],quantity,price));}case "buy", "sell" -> {if(a.length<4){msg(p,"/tm "+a[0]+" <stock|crypto> <企業名または記号> <数量>");break;}msg(p,"旧式即時売買は注文板移行後、/tm order を使用してください。");}case "market" -> {msg(p,"--- Market ---");service.market().forEach(x->msg(p,x));}case "gui" -> gui.open(p);default -> msg(p,"不明なコマンドです。/tm help");} } catch(NumberFormatException e){msg(p,"数値が不正です。");} return true;
    }
    @Override public List<String> onTabComplete(CommandSender s,Command c,String l,String[] a){if(a.length==1)return List.of("help","company","list","foreign","crypto","mine","stake","unstake","balance","funds","dividend","tax","taxinfo","passcode","approval","approve","credit","relation","employment","benefit","invoice","companyinfo","closecompany","rate","meeting","autodividend","order","buy","sell","market","gui").stream().filter(x->x.startsWith(a[0].toLowerCase())).toList();return List.of();}
}
